use anyhow::{Context, Result};
use std::collections::HashMap;
use std::fs;
use std::process::Command;

/// Print Terraform TF_VAR_* exports for the given environment.
///
/// Resolves the external provider secrets from the repo-root .env (e.g.
/// PROVIDER_TENSORX_API_KEY_STAGING, MOJEEK_API_KEY_STAGING), fetches the Scaleway secret key via
/// the scw CLI, and prints the export lines to stdout suitable for eval. Non-secret config
/// lives in environments/*.tfvars and our own secrets are generated by Terraform, so
/// neither is emitted here.
///
/// Also emits AWS_* credentials for the S3 remote-state backend, read at init time. These
/// prefer the scoped state key from .env (TFSTATE_ACCESS_KEY / TFSTATE_SECRET_KEY /
/// TFSTATE_REGION) and fall back to the scw CLI config. Harmless when using the local backend.
#[derive(clap::Args)]
pub struct TfVarsArgs {
    /// Environment name (e.g. staging, production).
    pub env: String,
}

pub fn run(args: TfVarsArgs) -> Result<()> {
    let env_upper = args.env.to_uppercase();

    let repo_root = repo_root()?;
    let dot_env = parse_dot_env(&format!("{repo_root}/.env"));

    let mojeek_key = dot_env
        .get(&format!("MOJEEK_API_KEY_{env_upper}"))
        .map(String::as_str)
        .unwrap_or("");

    // Optional previous relay key, kept accepted during a rotation. Empty when unset;
    // Terraform omits the secret env var in that case.
    let eigin_relay_secondary_key = dot_env
        .get(&format!("EIGIN_RELAY_SECONDARY_KEY_{env_upper}"))
        .map(String::as_str)
        .unwrap_or("");

    // Optional previous token encryption key, set only during a token-key rotation so the
    // relay can decrypt tokens minted under the old key until a sweep re-encrypts them.
    let token_encryption_secondary_key = dot_env
        .get(&format!("TOKEN_ENCRYPTION_SECONDARY_KEY_{env_upper}"))
        .map(String::as_str)
        .unwrap_or("");

    let provider_api_keys_json = serde_json::to_string(&provider_api_keys(&dot_env, &env_upper))?;

    let alerts_email = resolve_alerts_email(&dot_env);

    let scw_secret = scw_config_get("secret-key").unwrap_or_default();
    let scw_access_key = scw_config_get("access-key").unwrap_or_default();
    let scw_region = scw_config_get("default-region").unwrap_or_default();
    let image_tag = git_short_head().unwrap_or_default();

    // Backend creds: the scoped state key from .env wins, scw config is the fallback.
    let (aws_access, aws_secret, aws_region) =
        resolve_backend_creds(&dot_env, &scw_access_key, &scw_secret, &scw_region);

    println!("export TF_VAR_scw_secret_key=\"{scw_secret}\"");
    println!("export TF_VAR_image_tag=\"{image_tag}\"");
    println!("export TF_VAR_mojeek_api_key=\"{mojeek_key}\"");
    println!("export TF_VAR_eigin_relay_secondary_key=\"{eigin_relay_secondary_key}\"");
    println!("export TF_VAR_token_encryption_secondary_key=\"{token_encryption_secondary_key}\"");
    println!("export TF_VAR_provider_api_keys='{provider_api_keys_json}'");
    println!("export TF_VAR_alerts_email=\"{alerts_email}\"");

    // S3 remote-state backend credentials.
    print!("{}", aws_exports(&aws_access, &aws_secret, &aws_region));

    Ok(())
}

/// Resolve the S3 backend credentials, preferring the scoped state key from `.env`
/// (`TFSTATE_ACCESS_KEY` / `TFSTATE_SECRET_KEY` / `TFSTATE_REGION`) over the scw CLI
/// config fallback. Each field falls back independently.
fn resolve_backend_creds(
    dot_env: &HashMap<String, String>,
    scw_access_key: &str,
    scw_secret: &str,
    scw_region: &str,
) -> (String, String, String) {
    let pick = |key: &str, fallback: &str| {
        dot_env
            .get(key)
            .filter(|v| !v.is_empty())
            .cloned()
            .unwrap_or_else(|| fallback.to_string())
    };
    (
        pick("TFSTATE_ACCESS_KEY", scw_access_key),
        pick("TFSTATE_SECRET_KEY", scw_secret),
        pick("TFSTATE_REGION", scw_region),
    )
}

/// Build the AWS_* export lines the S3 backend reads for remote state.
fn aws_exports(access_key: &str, secret_key: &str, region: &str) -> String {
    format!(
        "export AWS_ACCESS_KEY_ID=\"{access_key}\"\n\
         export AWS_SECRET_ACCESS_KEY=\"{secret_key}\"\n\
         export AWS_DEFAULT_REGION=\"{region}\"\n"
    )
}

/// Build the `provider_api_keys` map for Terraform from a parsed `.env`: every
/// `PROVIDER_<NAME>_API_KEY_<ENV>` entry becomes `<name>` (lowercased) → key.
/// Entries for other environments, non-provider keys, and an empty `<NAME>` are
/// ignored.
fn provider_api_keys(
    dot_env: &HashMap<String, String>,
    env_upper: &str,
) -> HashMap<String, String> {
    let suffix = format!("_API_KEY_{env_upper}");
    dot_env
        .iter()
        .filter_map(|(key, value)| {
            let name = key.strip_prefix("PROVIDER_")?.strip_suffix(&suffix)?;
            if name.is_empty() {
                return None;
            }
            Some((name.to_lowercase(), value.clone()))
        })
        .collect()
}

/// Resolve the alert email: dedicated `EIGIN_ALERTS_EMAIL` wins over the
/// support inbox `EIGIN_SUPPORT_EMAIL` (which itself may be unset).
pub fn resolve_alerts_email(dot_env: &HashMap<String, String>) -> String {
    dot_env
        .get("EIGIN_ALERTS_EMAIL")
        .or_else(|| dot_env.get("EIGIN_SUPPORT_EMAIL"))
        .cloned()
        .unwrap_or_else(|| "support@eigin.ai".into())
}

fn repo_root() -> Result<String> {
    let out = Command::new("git")
        .args(["rev-parse", "--show-toplevel"])
        .output()
        .context("running git rev-parse --show-toplevel")?;
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// Parse a `.env` file into a map. Silently returns an empty map if the file doesn't exist.
pub fn parse_dot_env(path: &str) -> HashMap<String, String> {
    let Ok(content) = fs::read_to_string(path) else {
        return HashMap::new();
    };
    content
        .lines()
        .filter_map(|line| {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                return None;
            }
            let line = line.strip_prefix("export ").unwrap_or(line);
            let (key, value) = line.split_once('=')?;
            let value = value.trim_matches('"').trim_matches('\'').to_string();
            Some((key.to_string(), value))
        })
        .collect()
}

fn scw_config_get(key: &str) -> Option<String> {
    let out = Command::new("scw")
        .args(["config", "get", key])
        .output()
        .ok()?;
    if out.status.success() {
        Some(String::from_utf8_lossy(&out.stdout).trim().to_string())
    } else {
        None
    }
}

fn git_short_head() -> Option<String> {
    let out = Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .ok()?;
    if out.status.success() {
        Some(String::from_utf8_lossy(&out.stdout).trim().to_string())
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn env(pairs: &[(&str, &str)]) -> HashMap<String, String> {
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect()
    }

    #[test]
    fn extracts_and_lowercases_provider_names() {
        let dot_env = env(&[
            ("PROVIDER_TENSORX_API_KEY_STAGING", "tensorx-key"),
            ("PROVIDER_MISTRAL_API_KEY_STAGING", "mistral-key"),
        ]);
        let keys = provider_api_keys(&dot_env, "STAGING");
        assert_eq!(keys.get("tensorx").map(String::as_str), Some("tensorx-key"));
        assert_eq!(keys.get("mistral").map(String::as_str), Some("mistral-key"));
        assert_eq!(keys.len(), 2);
    }

    #[test]
    fn ignores_other_keys_and_environments() {
        let dot_env = env(&[
            ("PROVIDER_TENSORX_API_KEY_STAGING", "stg"),
            ("PROVIDER_TENSORX_API_KEY_PRODUCTION", "prod"),
            ("MOJEEK_API_KEY_STAGING", "mojeek"),
            ("SOME_OTHER_VALUE", "x"),
        ]);
        let keys = provider_api_keys(&dot_env, "STAGING");
        assert_eq!(keys.get("tensorx").map(String::as_str), Some("stg"));
        assert_eq!(keys.len(), 1);
    }

    #[test]
    fn ignores_empty_provider_name() {
        let dot_env = env(&[("PROVIDER__API_KEY_STAGING", "orphan")]);
        assert!(provider_api_keys(&dot_env, "STAGING").is_empty());
    }

    #[test]
    fn empty_when_no_provider_keys() {
        let dot_env = env(&[("MOJEEK_API_KEY_STAGING", "mojeek")]);
        assert!(provider_api_keys(&dot_env, "STAGING").is_empty());
    }

    #[test]
    fn backend_creds_prefer_dot_env_over_scw() {
        let dot_env = env(&[
            ("TFSTATE_ACCESS_KEY", "scoped-access"),
            ("TFSTATE_SECRET_KEY", "scoped-secret"),
            ("TFSTATE_REGION", "nl-ams"),
        ]);
        let creds = resolve_backend_creds(&dot_env, "scw-access", "scw-secret", "fr-par");
        assert_eq!(
            creds,
            (
                "scoped-access".to_string(),
                "scoped-secret".to_string(),
                "nl-ams".to_string()
            )
        );
    }

    #[test]
    fn backend_creds_fall_back_to_scw_per_field() {
        // Only the access key is overridden in .env; secret and region fall back.
        let dot_env = env(&[("TFSTATE_ACCESS_KEY", "scoped-access")]);
        let creds = resolve_backend_creds(&dot_env, "scw-access", "scw-secret", "fr-par");
        assert_eq!(
            creds,
            (
                "scoped-access".to_string(),
                "scw-secret".to_string(),
                "fr-par".to_string()
            )
        );
    }

    #[test]
    fn emits_aws_credential_exports() {
        let exports = aws_exports("SCWACCESS", "scw-secret", "fr-par");
        assert_eq!(
            exports,
            "export AWS_ACCESS_KEY_ID=\"SCWACCESS\"\n\
             export AWS_SECRET_ACCESS_KEY=\"scw-secret\"\n\
             export AWS_DEFAULT_REGION=\"fr-par\"\n"
        );
    }

    #[test]
    fn alerts_email_prefers_dedicated_key_over_support() {
        let dot_env = env(&[
            ("EIGIN_ALERTS_EMAIL", "alerts@eigin.ai"),
            ("EIGIN_SUPPORT_EMAIL", "support@eigin.ai"),
        ]);
        assert_eq!(resolve_alerts_email(&dot_env), "alerts@eigin.ai");
    }

    #[test]
    fn alerts_email_falls_back_to_support_then_default() {
        let support_only = env(&[("EIGIN_SUPPORT_EMAIL", "support@eigin.ai")]);
        assert_eq!(resolve_alerts_email(&support_only), "support@eigin.ai");
        assert_eq!(resolve_alerts_email(&HashMap::new()), "support@eigin.ai");
    }
}
